"""Native nonlocal footprint guard for a direct rectangular quad strip.

Positive quad corner Jacobians prevent local folds. They do not prevent a
distant portion of a long path from crossing an earlier portion. This helper
requires the complete generated strip boundary to be a simple closed polygon:
proper crossings, nonadjacent contacts and collinear overlaps are rejected.
No positions are moved and no triangles are generated.
"""

CONTACT_TOLERANCE = 1.e-6
MAX_BOUNDARY_EDGES = 4096
# The independent linear certificate can handle the complete bounded Bundle
# output (at most 16,384 station rows). The quadratic fallback keeps its budget.
MAX_CERTIFIED_BOUNDARY_EDGES = 32768
# Bounded batches avoid one expensive Repeat iteration per boundary edge.
# The alternate schedule is retained only for the reproducible benchmark.
BATCH_PAIR_CHECKS = True
PAIR_BATCH_SIZE = 16384


def monotone_certificate(g, mesh, ny, nx, index, pos, axis):
    """Sufficient linear-time proof for a strip of ordered convex XY cells.

    Project both vertices of each outer cross-section onto ``axis``. Require
    each row's entire projection interval to precede the next row, and all
    outer-envelope cells to be strictly convex with one consistent winding.
    Nonneighbor cells then occupy disjoint axial slabs. Neighboring convex
    cells lie on opposite sides of their shared cross-section. Their union
    therefore has a simple perimeter, including both terminal cross-sections.

    This is a sufficient certificate, not a relaxed intersection test. A
    folded, skewed, numerically unresolved or nonconvex strip falls back to the
    exhaustive check. All emitted rows participate; no geometry is simplified.
    """
    margin = 4. * CONTACT_TOLERANCE
    axis = g.vector('NORMALIZE', g.xyz(g.component(axis, 'X'), g.component(axis, 'Y')))
    rows = g.node('GeometryNodeMeshLine', 'Linear proof: every outer-envelope cell')
    g.set(g.math('MAXIMUM', 1., g.math('SUBTRACT', ny, 1.)), rows.inputs['Count'])
    base = g.math('MULTIPLY', g.math('SUBTRACT', nx, 1.), ny)
    points = [g.sample(mesh, pos, at, 'FLOAT_VECTOR') for at in
              (index, g.math('ADD', index, 1.),
               g.math('ADD', base, g.math('ADD', index, 1.)), g.math('ADD', base, index))]
    points = [g.xyz(g.component(p, 'X'), g.component(p, 'Y')) for p in points]
    # Compare relative projections within each cell. Subtracting two large
    # absolute dot products can erase a valid micrometre-scale row separation
    # after an edit. Translating all four points by the same origin leaves
    # the slab-order proof and its physical margin unchanged.
    axial = [g.vector('DOT_PRODUCT', g.vector('SUBTRACT', p, points[0]), axis) for p in points]
    advance = g.math('SUBTRACT', g.math('MINIMUM', axial[1], axial[2]),
                     g.math('MAXIMUM', axial[0], axial[3]))
    ordered = g.stat(rows.outputs['Mesh'], g.compare(advance, margin, 'GREATER_THAN'))
    positive, negative = [], []
    for k in range(4):
        a, b, c = [points[(k+j) % 4] for j in range(3)]
        ab, bc = g.vector('SUBTRACT', b, a), g.vector('SUBTRACT', c, b)
        cross = g.component(g.vector('CROSS_PRODUCT', ab, bc), 'Z')
        threshold = g.math('MULTIPLY', margin,
                           g.math('MAXIMUM', g.vector('LENGTH', ab), g.vector('LENGTH', bc)))
        positive.append(g.compare(cross, threshold, 'GREATER_THAN'))
        negative.append(g.compare(cross, g.math('MULTIPLY', -1., threshold), 'LESS_THAN'))
    convex = g.either(g.stat(rows.outputs['Mesh'], g.all(*positive)),
                      g.stat(rows.outputs['Mesh'], g.all(*negative)))
    return g.all(g.compare(ny, 2, 'GREATER_EQUAL'), g.compare(nx, 2, 'GREATER_EQUAL'), ordered, convex)


def check_strip(g, mesh, ny, nx, index, pos, simplify_straights=False, monotone_axis=None, monotone_graphs=False,
                blocked_boundary=False):
    """Return scalar validity for grid vertex ordering ``u_index*ny+s_index``.

    ``nx`` and ``ny`` are vertex counts, not interval counts. All four boundary
    sides are included; neighboring boundary edges may share their one endpoint.
    Every other contact invalidates the strip. The caller separately checks
    convex, positively oriented quads and gates invalid output.

    The end rows are straight in XY, so their intermediate transverse vertices
    are omitted exactly. If ``simplify_straights`` is true, the caller certifies
    that side edges between POINT ``st_path_knot`` rows are exactly straight:
    retaining only those mandatory rows is then an exact polygon reduction,
    with no angle tolerance or geometric approximation. Smooth sides retain
    every generated row. A missing mandatory-knot attribute invalidates this
    optional mode. At most 4096 boundary edges are tested; larger boundaries
    return false before entering the quadratic pair scan.

    With ``monotone_axis``, an independent ordered-convex-cell certificate can
    prove up to 32768 boundary edges in linear work. Indeterminate cases still
    use the complete scan under its original 4096-edge budget. Both branches
    require the knot contract and nondegenerate physical edges.

    ``monotone_graphs`` adds a second sufficient proof from the complete two
    side graphs and original end caps. It is useful when densely sampled skew
    rows overlap in axial projection. It never changes the exhaustive budget.

    blocked_boundary permits larger boundaries through conservative edge-block
    boxes and a complete narrow-phase scan. No smooth side samples are removed.
    """
    if monotone_graphs and monotone_axis is None:
        raise ValueError('The boundary graph proof requires an explicit axis')
    count = g.math('MULTIPLY', 2., ny)
    perimeter = g.node('GeometryNodeMeshLine', 'Complete ordered strip perimeter')
    g.set(count, perimeter.inputs['Count'])
    # Left side upwards, right side downwards. Their endpoints connect through
    # complete straight-in-XY profile rows; intermediate row vertices add no
    # footprint information even when their crown heights are nonzero.
    right_side = g.math('ADD', g.math('MULTIPLY', g.math('SUBTRACT', nx, 1.), ny),
                        g.math('SUBTRACT', g.math('SUBTRACT', count, 1.), index))
    source_index = g.switch(g.compare(index, ny, 'LESS_THAN'), right_side, index, 'INT')
    positions = g.node('GeometryNodeSetPosition', 'Actual generated boundary coordinates')
    g.set(perimeter.outputs['Mesh'], positions.inputs['Geometry'])
    g.set(g.sample(mesh, pos, source_index, 'FLOAT_VECTOR'), positions.inputs['Position'])
    boundary = positions.outputs['Geometry']
    knot = g.node('GeometryNodeInputNamedAttribute', 'Mandatory exact side-boundary knots')
    knot.data_type = 'BOOLEAN'
    knot.inputs['Name'].default_value = 'st_path_knot'
    knot_exists = g.sample(mesh, knot.outputs['Exists'], 0, 'BOOLEAN')
    is_knot = g.sample(mesh, knot.outputs['Attribute'], source_index, 'BOOLEAN')
    is_corner = g.either(g.either(g.compare(index, 0.), g.compare(index, g.math('SUBTRACT', ny, 1.))),
                         g.either(g.compare(index, ny), g.compare(index, g.math('SUBTRACT', count, 1.))))
    retained = g.switch(simplify_straights, True, g.either(is_knot, is_corner), 'BOOLEAN')
    separate = g.node('GeometryNodeSeparateGeometry', 'Exact reduction to mandatory straight-side knots')
    separate.domain = 'POINT'
    g.set(boundary, separate.inputs['Geometry'])
    g.set(retained, separate.inputs['Selection'])
    boundary = separate.outputs['Selection']
    size = g.node('GeometryNodeAttributeDomainSize', 'Actual tested boundary size')
    size.component = 'MESH'
    g.set(boundary, size.inputs['Geometry'])
    count = size.outputs['Point Count']
    certificate = None
    if monotone_axis is not None:
        proof=monotone_certificate(g, mesh, ny, nx, index, pos, monotone_axis)
        if monotone_graphs:
            from . import monotone_boundary_nodes
            proof=g.either(proof,monotone_boundary_nodes.certificate(g,mesh,ny,nx,index,pos,monotone_axis,CONTACT_TOLERANCE))
        following = g.math('MODULO', g.math('ADD', index, 1.), count)
        end = g.sample(boundary, pos, following, 'FLOAT_VECTOR')
        nonzero = g.stat(boundary, g.compare(g.vector('DISTANCE', pos, end),
                                            CONTACT_TOLERANCE, 'GREATER_THAN'))
        certificate = g.all(g.compare(count, 4., 'GREATER_EQUAL'),
            g.compare(count, MAX_CERTIFIED_BOUNDARY_EDGES, 'LESS_EQUAL'),
            g.compare(g.math('MULTIPLY', 2., ny), MAX_CERTIFIED_BOUNDARY_EDGES, 'LESS_EQUAL'),
            g.switch(simplify_straights, True, knot_exists, 'BOOLEAN'), nonzero,
            proof)
    within_budget = g.all(g.compare(count, 4., 'GREATER_EQUAL'),
                         g.compare(count, MAX_BOUNDARY_EDGES, 'LESS_EQUAL'),
                         g.switch(simplify_straights, True, knot_exists, 'BOOLEAN'))
    blocked=None
    if blocked_boundary:
        from . import blocked_boundary_nodes
        blocked=g.all(g.switch(simplify_straights,True,knot_exists,'BOOLEAN'),
            blocked_boundary_nodes.check(g,boundary,count,index,pos,CONTACT_TOLERANCE))
        needs_blocks=g.compare(count,MAX_BOUNDARY_EDGES,'GREATER_THAN')
    fallback = g.node('GeometryNodeMeshLine', 'Bounded computation for rejected perimeter work')
    fallback.inputs['Count'].default_value = 2
    boundary = g.switch(within_budget, fallback.outputs['Mesh'], boundary, 'GEOMETRY')
    count = g.switch(within_budget, 2, count, 'INT')
    following = g.math('MODULO', g.math('ADD', index, 1.), count)
    end = g.sample(boundary, pos, following, 'FLOAT_VECTOR')
    boundary = g.store(boundary, 'st_overlap_end', end, 'FLOAT_VECTOR')
    boundary = g.store(boundary, 'st_overlap_edge', index, 'INT')
    length = g.vector('DISTANCE', pos, g.named('st_overlap_end', 'FLOAT_VECTOR'))
    nondegenerate = g.stat(boundary, g.compare(length, CONTACT_TOLERANCE, 'GREATER_THAN'))

    ri = g.node('GeometryNodeRepeatInput', 'Compare each boundary edge with later nonneighbors')
    ro = g.node('GeometryNodeRepeatOutput', 'Complete strip footprint has no self-contact')
    ro.repeat_items.clear()
    ro.repeat_items.new('BOOLEAN', 'Valid')
    ri.pair_with_output(ro)
    if BATCH_PAIR_CHECKS:
        pair_count = g.math('MULTIPLY', count, count)
        batches = g.math('CEIL', g.math('DIVIDE', pair_count, PAIR_BATCH_SIZE))
        g.set(batches, ri.inputs['Iterations'])
    else:
        g.set(count, ri.inputs['Iterations'])
    g.set(g.all(within_budget, nondegenerate), ri.inputs['Valid'])
    if BATCH_PAIR_CHECKS:
        batch_start = g.math('MULTIPLY', ri.outputs['Iteration'], PAIR_BATCH_SIZE)
        points = g.node('GeometryNodePoints', 'Bounded batches of complete boundary-edge pairs')
        batch_count = g.math('MINIMUM', PAIR_BATCH_SIZE, g.math('SUBTRACT', pair_count, batch_start))
        g.set(batch_count, points.inputs['Count'])
        pairs = g.store(points.outputs['Points'], 'st_overlap_pair', g.math('ADD', batch_start, index), 'INT')
        pair_index = g.named('st_overlap_pair')
        current = g.math('FLOOR', g.math('DIVIDE', pair_index, count))
        other = g.math('MODULO', pair_index, count)
    else:
        current = ri.outputs['Iteration']
        other = g.named('st_overlap_edge')
    a = g.sample(boundary, pos, current, 'FLOAT_VECTOR')
    b = g.sample(boundary, g.named('st_overlap_end', 'FLOAT_VECTOR'), current, 'FLOAT_VECTOR')
    if BATCH_PAIR_CHECKS:
        c = g.sample(boundary, pos, other, 'FLOAT_VECTOR')
        d = g.sample(boundary, g.named('st_overlap_end', 'FLOAT_VECTOR'), other, 'FLOAT_VECTOR')
    else:
        c, d = pos, g.named('st_overlap_end', 'FLOAT_VECTOR')
    later = g.compare(other, g.math('ADD', current, 1.), 'GREATER_THAN')
    closing_neighbors = g.all(g.compare(current, 0., 'EQUAL'),
                              g.compare(other, g.math('SUBTRACT', count, 1.), 'EQUAL'))
    candidate = g.all(later, g.boolean('NOT', closing_neighbors))
    if BATCH_PAIR_CHECKS:
        nonneighbors = g.node('GeometryNodeSeparateGeometry', 'Skip duplicate and neighboring edge pairs before sampling bounds')
        nonneighbors.domain = 'POINT'
        g.set(pairs, nonneighbors.inputs['Geometry'])
        g.set(candidate, nonneighbors.inputs['Selection'])
        pairs = nonneighbors.outputs['Selection']

    def line_distance(first, second, query):
        direction = g.vector('SUBTRACT', second, first)
        relative = g.vector('SUBTRACT', query, first)
        area = g.component(g.vector('CROSS_PRODUCT', direction, relative), 'Z')
        return g.math('DIVIDE', area, g.math('MAXIMUM', g.vector('LENGTH', direction), 1.e-12))

    def straddles(first, second):
        return g.either(
            g.all(g.compare(first, CONTACT_TOLERANCE, 'LESS_EQUAL'),
                  g.compare(second, -CONTACT_TOLERANCE, 'GREATER_EQUAL')),
            g.all(g.compare(second, CONTACT_TOLERANCE, 'LESS_EQUAL'),
                  g.compare(first, -CONTACT_TOLERANCE, 'GREATER_EQUAL')))

    ab_c, ab_d = line_distance(a, b, c), line_distance(a, b, d)
    cd_a, cd_b = line_distance(c, d, a), line_distance(c, d, b)
    boxes = []
    for axis in ('X', 'Y'):
        a_axis, b_axis, c_axis, d_axis = [g.component(point, axis) for point in (a, b, c, d)]
        low = g.math('MAXIMUM', g.math('MINIMUM', a_axis, b_axis), g.math('MINIMUM', c_axis, d_axis))
        high = g.math('MINIMUM', g.math('MAXIMUM', a_axis, b_axis), g.math('MAXIMUM', c_axis, d_axis))
        boxes.append(g.compare(low, g.math('ADD', high, CONTACT_TOLERANCE), 'LESS_EQUAL'))
    if BATCH_PAIR_CHECKS:
        # Preserve pair indices through filtering. Bounding boxes use the same
        # tolerance as the old guard; only provably separated/adjacent pairs
        # are removed before the four exact line-distance queries.
        selected = g.node('GeometryNodeSeparateGeometry', 'Test contacts only for overlapping nonneighbor boxes')
        selected.domain = 'POINT'
        g.set(pairs, selected.inputs['Geometry'])
        g.set(g.all(*boxes), selected.inputs['Selection'])
        contact = g.all(straddles(ab_c, ab_d), straddles(cd_a, cd_b))
        clear = g.stat(selected.outputs['Selection'], contact, output='Max')
    else:
        contact = g.all(candidate, *boxes, straddles(ab_c, ab_d), straddles(cd_a, cd_b))
        clear = g.stat(boundary, contact, output='Max')
    g.set(g.all(ri.outputs['Valid'], g.compare(clear, .5, 'LESS_THAN')), ro.inputs['Valid'])
    result=ro.outputs['Valid']
    if blocked_boundary:result=g.switch(needs_blocks,result,blocked,'BOOLEAN')
    if monotone_axis is not None:
        # Lazy Switch evaluation skips the pair scan only after the
        # independent sufficient proof succeeds. Large indeterminate strips
        # still fail the original exhaustive-work budget before pair scanning.
        return g.switch(certificate, result, True, 'BOOLEAN')
    return result
